'use client';

import { useState } from 'react';
import { BookingList, BookingDetails } from '@/components/booking';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { ArrowLeftIcon } from 'lucide-react';
import type { Booking } from '@/common/interfaces';

export default function BookingsPage() {
  const [selectedBooking, setSelectedBooking] = useState<Booking | null>(null);
  const [view, setView] = useState<'list' | 'details'>('list');

  const handleBookingSelect = (booking: Booking) => {
    setSelectedBooking(booking);
    setView('details');
  };

  const handleBackToList = () => {
    setSelectedBooking(null);
    setView('list');
  };

  const handleBookingUpdate = (bookingId: string) => {
    // Handle booking update - could navigate to edit form
    console.log('Update booking:', bookingId);
  };

  const handleBookingCancel = (bookingId: string) => {
    // Handle booking cancellation
    console.log('Booking cancelled:', bookingId);
    // Optionally show a success message
  };

  const handlePaymentRequired = (bookingId: string) => {
    // Handle payment requirement - could navigate to payment page
    console.log('Payment required for booking:', bookingId);
    // You could navigate to a payment page here
    // router.push(`/bookings/${bookingId}/payment`);
  };

  return (
    <main className="global-container py-8">
      <div className="max-w-6xl mx-auto">
        {view === 'list' ? (
          <div className="space-y-6">
            <Card>
              <CardHeader>
                <CardTitle className="text-2xl">My Bookings</CardTitle>
                <p className="text-gray-600">
                  Manage your car rental bookings and view booking history.
                </p>
              </CardHeader>
            </Card>

            <BookingList
              onBookingSelect={handleBookingSelect}
              onBookingUpdate={handleBookingUpdate}
              onBookingCancel={handleBookingCancel}
            />
          </div>
        ) : (
          <div className="space-y-6">
            <div className="flex items-center gap-4">
              <Button
                variant="outline"
                size="sm"
                onClick={handleBackToList}
                className="flex items-center gap-2"
              >
                <ArrowLeftIcon className="h-4 w-4" />
                Back to Bookings
              </Button>
              <h1 className="text-2xl font-bold">Booking Details</h1>
            </div>

            {selectedBooking && (
              <BookingDetails
                bookingId={selectedBooking.id}
                onClose={handleBackToList}
                onPaymentRequired={handlePaymentRequired}
              />
            )}
          </div>
        )}
      </div>
    </main>
  );
}